            width: '90%',
            boxShadow: '0 5px 20px rgba(0,0,0,0.3)',
            position: 'relative',
        },
        closeButton: {
            position: 'absolute',
            top: '1rem',
            right: '1rem',
            background: 'none',
            border: 'none',
